// Issue schema and registry v0.
//
// Turns what the detectors found into ONE list of typed issues, each carrying
// the evidence a human (and later the AI layer) needs. Pure functions.
//
// An issue is a FACT: the crawler measured it. Nothing here is generated by AI.
// Later days add the AI explanation as a separate field and track status across
// runs; v0 is a single run's snapshot.
import { createHash } from "node:crypto";

export const SCHEMA_VERSION = 1;
export const SEVERITIES = ["high", "medium", "low"];
export const STATUSES = ["open"]; // Day 7 adds acknowledged / fixed / verified / reopened

// fixClass follows the README's four fix categories. Every fix still needs human approval.
//   deterministic    one unambiguous answer (e.g. point a link straight at the final URL)
//   ai-proposed      AI may draft the change from the evidence; a human approves it
//   not-automatable  detected only; routed to a manual ticket
// Categories are grouped by who reads the tag, which decides the impact and who fixes it:
//   SEO: titles & descriptions  Google's results page    SEO: indexing   Google's crawler
//   Social sharing              link previews             Page setup      browsers, phones, screen readers
//   Content                     the people reading the page
export const CATALOG = {
    "http-4xx-internal": { category: "HTTP and URLs", severity: "high", fixClass: "ai-proposed" },
    "http-4xx-external": { category: "HTTP and URLs", severity: "medium", fixClass: "ai-proposed" },
    "link-unreachable": { category: "HTTP and URLs", severity: "medium", fixClass: "not-automatable" },
    "redirect-loop": { category: "HTTP and URLs", severity: "high", fixClass: "not-automatable" },
    "redirect-chain": { category: "HTTP and URLs", severity: "low", fixClass: "deterministic" },
    "redirect-to-error": { category: "HTTP and URLs", severity: "high", fixClass: "ai-proposed" },
    "https-missing-redirect": { category: "HTTP and URLs", severity: "high", fixClass: "not-automatable" },
    "www-variant-not-redirected": { category: "HTTP and URLs", severity: "medium", fixClass: "not-automatable" },
    "soft-404": { category: "Soft 404s", severity: "high", fixClass: "not-automatable" },
    "title-missing": { category: "SEO: titles & descriptions", severity: "high", fixClass: "ai-proposed" },
    "title-multiple": { category: "SEO: titles & descriptions", severity: "medium", fixClass: "ai-proposed" },
    "title-too-long": { category: "SEO: titles & descriptions", severity: "low", fixClass: "ai-proposed" },
    "title-too-short": { category: "SEO: titles & descriptions", severity: "low", fixClass: "ai-proposed" },
    "title-duplicate": { category: "SEO: titles & descriptions", severity: "medium", fixClass: "ai-proposed" },
    "description-missing": { category: "SEO: titles & descriptions", severity: "medium", fixClass: "ai-proposed" },
    "description-multiple": { category: "SEO: titles & descriptions", severity: "low", fixClass: "ai-proposed" },
    "description-too-long": { category: "SEO: titles & descriptions", severity: "low", fixClass: "ai-proposed" },
    "description-too-short": { category: "SEO: titles & descriptions", severity: "low", fixClass: "ai-proposed" },
    "description-duplicate": { category: "SEO: titles & descriptions", severity: "medium", fixClass: "ai-proposed" },
    "h1-missing": { category: "SEO: titles & descriptions", severity: "medium", fixClass: "ai-proposed" },
    "h1-multiple": { category: "SEO: titles & descriptions", severity: "low", fixClass: "ai-proposed" },
    "heading-skip": { category: "SEO: titles & descriptions", severity: "low", fixClass: "ai-proposed" },
    "metadata-js-only": { category: "SEO: titles & descriptions", severity: "medium", fixClass: "not-automatable" },
    "canonical-missing": { category: "SEO: indexing", severity: "medium", fixClass: "ai-proposed" },
    "canonical-multiple": { category: "SEO: indexing", severity: "high", fixClass: "ai-proposed" },
    "canonical-broken-target": { category: "SEO: indexing", severity: "high", fixClass: "ai-proposed" },
    "canonical-redirect": { category: "SEO: indexing", severity: "medium", fixClass: "deterministic" },
    "robots-noindex": { category: "SEO: indexing", severity: "medium", fixClass: "not-automatable" },
    "robots-nofollow": { category: "SEO: indexing", severity: "low", fixClass: "not-automatable" },
    "og-missing": { category: "Social sharing", severity: "low", fixClass: "ai-proposed" },
    "og-incomplete": { category: "Social sharing", severity: "low", fixClass: "ai-proposed" },
    "og-image-broken": { category: "Social sharing", severity: "medium", fixClass: "ai-proposed" },
    "viewport-missing": { category: "Page setup", severity: "medium", fixClass: "deterministic" },
    "lang-missing": { category: "Page setup", severity: "low", fixClass: "ai-proposed" },
    // Content: Phase 1 does not edit page copy (README section 7), so these are detected only.
    "content-thin": { category: "Content", severity: "low", fixClass: "not-automatable" },
    "content-duplicate": { category: "Content", severity: "medium", fixClass: "not-automatable" },
    "content-placeholder": { category: "Content", severity: "high", fixClass: "not-automatable" },
    "content-repeated-word": { category: "Content", severity: "low", fixClass: "not-automatable" },
    "image-broken": { category: "Images", severity: "high", fixClass: "ai-proposed" },
    "image-alt-missing": { category: "Images", severity: "medium", fixClass: "ai-proposed" },
    "image-alt-unhelpful": { category: "Images", severity: "low", fixClass: "ai-proposed" },
    "image-alt-too-long": { category: "Images", severity: "low", fixClass: "ai-proposed" },
    "image-mixed-content": { category: "Images", severity: "high", fixClass: "not-automatable" },
    "image-oversized": { category: "Images", severity: "medium", fixClass: "not-automatable" },
};

// Same type + same URL always gets the same id, so a later run can recognise it.
export function issueId(type, affectedUrl) {
    return "ISS-" + createHash("sha1").update(`${type}|${affectedUrl}`).digest("hex").slice(0, 10);
}

function makeIssue(run, { type, affectedUrl, foundOn = [], detail, evidence, severity }) {
    const meta = CATALOG[type];
    if (!meta) throw new Error(`Unknown issue type: ${type}`);
    return {
        id: issueId(type, affectedUrl),
        type,
        category: meta.category,
        severity: severity || meta.severity,
        affectedUrl,
        foundOn: [...foundOn].sort(),
        detail,
        evidence,
        fixClass: meta.fixClass,
        status: "open",
        firstSeenRun: run.id,
        lastSeenRun: run.id,
    };
}

const SEVERITY_ORDER = { high: 0, medium: 1, low: 2 };

// run: { id, startedAt, startUrl, pagesCrawled, capReached, toolVersion }
// links:     links.json entries            (broken links, redirects)
// siteChecks: result of siteLevelChecks
// metaPages: metadata.json pages           (issues, heads, canonical check)
// softPages: soft404.json pages            (only flagged ones become issues)
// imageFindings: drafts from lib/images.js imageFindings() (already one per issue)
// findings:  other ready-made drafts, e.g. lib/social.js ogImageFindings(), lib/content.js contentFindings()
export function buildRegistry({ run, links = [], siteChecks = null, metaPages = [], softPages = [], imageFindings = [], findings = [] }) {
    const out = [];
    const add = (x) => out.push(makeIssue(run, x));

    for (const l of links) {
        if (l.classification === "broken") {
            add({
                type: l.type === "internal" ? "http-4xx-internal" : "http-4xx-external",
                affectedUrl: l.url, foundOn: l.foundOn,
                detail: `Link returns ${l.status}`,
                evidence: { kind: "http", status: l.status, method: "HEAD, then GET if refused" },
            });
        } else if (l.classification === "unreachable") {
            add({
                type: "link-unreachable", affectedUrl: l.url, foundOn: l.foundOn,
                detail: `Link could not be reached (${l.error})`,
                evidence: { kind: "http", status: null, error: l.error },
            });
        }
        if (l.redirect?.issueType) {
            const r = l.redirect;
            add({
                type: r.issueType, affectedUrl: l.url, foundOn: l.foundOn,
                detail: r.issueType === "redirect-loop" ? `Redirect loop after ${r.hops} hop(s)`
                    : r.issueType === "redirect-chain" ? `${r.hops} redirects before the final page`
                        : `Redirects to ${r.finalUrl}, which returns ${r.finalStatus}`,
                evidence: { kind: "redirect", chain: r.chain, hops: r.hops, finalUrl: r.finalUrl, finalStatus: r.finalStatus },
            });
        }
    }

    for (const f of siteChecks?.findings || []) {
        add({ type: f.type, affectedUrl: f.url, foundOn: [], detail: f.detail, evidence: { kind: "site-check", detail: f.detail } });
    }

    for (const m of metaPages) {
        for (const i of m.issues) {
            const evidence = { kind: "head", view: "rendered", head: m.head };
            // Keep the raw HTML's version only when it differs (it differs when JavaScript changed the tags).
            if (m.rawHead && JSON.stringify(m.rawHead) !== JSON.stringify(m.head)) evidence.rawHead = m.rawHead;
            else if (m.rawHead) evidence.rawSameAsRendered = true;
            if (i.type.startsWith("canonical-") && m.canonical) evidence.canonical = m.canonical;
            if (m.canonicalCheck) evidence.canonicalCheck = m.canonicalCheck;
            add({ type: i.type, affectedUrl: m.url, foundOn: m.foundOn, detail: i.detail, severity: i.severity, evidence });
        }
    }

    for (const s of softPages.filter((p) => p.flagged)) {
        add({
            type: "soft-404", affectedUrl: s.url, foundOn: s.foundOn,
            detail: `Answers 200 but looks like an error page (${s.signals.map((x) => x.name).join(", ")})`,
            evidence: { kind: "soft-404", title: s.title ?? null, h1s: s.h1s ?? [], wordCount: s.wordCount ?? null, reachedOnlyThroughRedirects: s.via === "redirect-target", signals: s.signals },
        });
    }

    for (const f of [...imageFindings, ...findings]) add(f);

    out.sort((a, b) => SEVERITY_ORDER[a.severity] - SEVERITY_ORDER[b.severity] || a.type.localeCompare(b.type) || a.affectedUrl.localeCompare(b.affectedUrl));

    const countBy = (key) => out.reduce((acc, i) => ((acc[i[key]] = (acc[i[key]] || 0) + 1), acc), {});
    return {
        schemaVersion: SCHEMA_VERSION,
        run: { tool: "progrowth-sitefix-agent", ...run },
        counts: { total: out.length, bySeverity: countBy("severity"), byType: countBy("type") },
        issues: out,
    };
}

// Returns a list of problems; empty means the issue is well-formed.
export function validateIssue(i) {
    const errors = [];
    const need = (cond, msg) => { if (!cond) errors.push(`${i?.id || "?"}: ${msg}`); };
    need(i && typeof i === "object", "not an object");
    if (!i || typeof i !== "object") return errors;
    need(/^ISS-[0-9a-f]{10}$/.test(i.id), "bad id");
    need(CATALOG[i.type], `unknown type ${i.type}`);
    need(SEVERITIES.includes(i.severity), `bad severity ${i.severity}`);
    need(typeof i.affectedUrl === "string" && i.affectedUrl.length > 0, "missing affectedUrl");
    need(Array.isArray(i.foundOn), "foundOn must be an array");
    need(typeof i.detail === "string" && i.detail.length > 0, "missing detail");
    need(i.evidence && typeof i.evidence === "object" && typeof i.evidence.kind === "string", "missing evidence");
    need(["deterministic", "ai-proposed", "not-automatable"].includes(i.fixClass), `bad fixClass ${i.fixClass}`);
    need(STATUSES.includes(i.status), `bad status ${i.status}`);
    need(i.firstSeenRun && i.lastSeenRun, "missing run ids");
    if (CATALOG[i.type]) need(i.category === CATALOG[i.type].category, "category does not match type");
    return errors;
}

export function validateRegistry(reg) {
    const errors = [];
    if (reg.schemaVersion !== SCHEMA_VERSION) errors.push(`schemaVersion is ${reg.schemaVersion}, expected ${SCHEMA_VERSION}`);
    const ids = new Set();
    for (const i of reg.issues) {
        errors.push(...validateIssue(i));
        if (ids.has(i.id)) errors.push(`${i.id}: duplicate id`);
        ids.add(i.id);
    }
    if (reg.counts.total !== reg.issues.length) errors.push("counts.total does not match the number of issues");
    return errors;
}